'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var namedtypedtuple = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof namedtypedtuple, 'function', 'main export is a function' );
	t.end();
});

tape( 'a tuple has a `reduceRight` method', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point();

	t.strictEqual( hasProp( p, 'reduceRight' ), true, 'returns expected value' );
	t.strictEqual( isFunction( p.reduceRight ), true, 'returns expected value' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a tuple instance', function test( t ) {
	var values;
	var Point;
	var p;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ 1, 2 ] );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return p.reduceRight.call( value, fcn );
		};
	}

	function fcn( acc, v ) {
		return acc + v;
	}
});

tape( 'the method throws an error if provided a first argument which is not a function', function test( t ) {
	var values;
	var Point;
	var p;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point( [ 1, 2 ] );

	values = [
		'5',
		3.14,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return p.reduceRight( value );
		};
	}
});

tape( 'the method reduces tuple elements from right to left to a single value (no initial value)', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );
	out = p.reduceRight( fcn );

	t.strictEqual( out, 6, 'returns expected value' );
	t.end();

	function fcn( acc, v ) {
		return acc + v;
	}
});

tape( 'the method reduces tuple elements from right to left to a single value (initial value)', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );
	out = p.reduceRight( fcn, 10 );

	t.strictEqual( out, 16, 'returns expected value' );
	t.end();

	function fcn( acc, v ) {
		return acc + v;
	}
});

tape( 'the method provides the callback with five arguments', function test( t ) {
	var fieldNames;
	var indices;
	var values;
	var tuples;
	var Point;
	var p;

	indices = [];
	values = [];
	fieldNames = [];
	tuples = [];

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );
	p.reduceRight( fcn, 0 );

	t.deepEqual( values, [ 3, 2, 1 ], 'returns expected value' );
	t.deepEqual( indices, [ 2, 1, 0 ], 'returns expected value' );
	t.deepEqual( fieldNames, [ 'z', 'y', 'x' ], 'returns expected value' );
	t.strictEqual( tuples[ 0 ], p, 'returns expected value' );
	t.strictEqual( tuples[ 1 ], p, 'returns expected value' );
	t.strictEqual( tuples[ 2 ], p, 'returns expected value' );

	t.end();

	function fcn( acc, v, i, fieldName, tuple ) {
		values.push( v );
		indices.push( i );
		fieldNames.push( fieldName );
		tuples.push( tuple );
		return acc + v;
	}
});

tape( 'when no initial value is provided, the method uses the last element as the initial value and starts iteration from the second-to-last element', function test( t ) {
	var indices;
	var values;
	var Point;
	var p;

	indices = [];
	values = [];

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );
	p.reduceRight( fcn );

	t.deepEqual( values, [ 2, 1 ], 'returns expected value' );
	t.deepEqual( indices, [ 1, 0 ], 'returns expected value' );

	t.end();

	function fcn( acc, v, i ) {
		values.push( v );
		indices.push( i );
		return acc + v;
	}
});
